insert into produk (slug,nama,nama_en,kategori,deskripsi,deskripsi_en,harga,supply_ability,packaging,payment_terms,fitur,quickspecs,lead_time,spesifikasi,gambar_url,status,urutan)
values ('coco-fiber','Coco Fiber','Coco Fiber','Serat Sabut Kelapa','Diperoleh dari sabut kelapa tua, coco fiber diproses secara mekanis melalui penghancuran, pencucian, dan pengeringan, menghasilkan serat alami yang kuat, tahan lama, dan 100% ramah lingkungan untuk kebutuhan industri maupun pertanian.','Obtained from mature coconut husk, coconut coir fiber is extracted through mechanical processing, including crushing, washing, and drying, producing a strong, durable, and 100% natural fiber for industrial and agricultural use.','$260–300 USD / MT','300 Ton / Bulan','18 Ton / Kontainer 40ft (HC)','L/C, T/T','[{"id": "100% Alami & Biodegradable", "en": "100% Natural & Biodegradable"}, {"id": "Ideal untuk Matras, Kontrol Erosi & Hortikultura", "en": "Ideal for Mattresses, Erosion Control & Horticulture"}, {"id": "Tersedia dalam Bentuk Bal & Curah", "en": "Available in Baled and Loose Form"}]'::jsonb,'[{"label_id": "Supply Ability", "label_en": "Supply Ability", "value": "300 Ton / Bulan", "value_en": "300 Metric Tons / Month", "sub": ""}, {"label_id": "Kemasan & Pengiriman", "label_en": "Packaging & Delivery", "value": "18 Ton / Kontainer 40ft (HC)", "value_en": "18 Ton per 40ft Container (HC)", "sub": ""}, {"label_id": "Harga", "label_en": "Price", "value": "$260–300 USD / MT", "value_en": "", "sub": "Min. Order 18 MT (1 Kontainer)"}, {"label_id": "Pembayaran", "label_en": "Payment Terms", "value": "L/C, T/T", "value_en": "", "sub": ""}]'::jsonb,'[{"qty": "1 – 18 MT", "qty_en": "", "waktu": "14 hari", "waktu_en": "14 days"}, {"qty": "> 20 MT", "qty_en": "", "waktu": "Nego", "waktu_en": "To be negotiated"}]'::jsonb,'[{"label_id": "Asal Produksi", "label_en": "Place of Origin", "value": "Sidoarjo, Jawa Timur", "value_en": "Sidoarjo, East Java, Indonesia"}, {"label_id": "Nama Produk", "label_en": "Product Name", "value": "Coconut Coir Fiber", "value_en": "Coconut Coir Fiber"}, {"label_id": "Material", "label_en": "Material", "value": "100% Coco Fiber Alami", "value_en": "100% Natural Coco Fiber"}, {"label_id": "Warna", "label_en": "Color", "value": "Coklat Keemasan", "value_en": "Golden Brown"}, {"label_id": "Kadar Air", "label_en": "Moisture", "value": "≤ 17%", "value_en": ""}, {"label_id": "Panjang Serat", "label_en": "Fiber Length", "value": "100–200mm", "value_en": ""}, {"label_id": "Kotoran", "label_en": "Impurity", "value": "≤ 5%", "value_en": ""}, {"label_id": "Kemasan", "label_en": "Package", "value": "95–130 kg / bal", "value_en": "95–130 kg / bale"}, {"label_id": "Muatan Kontainer", "label_en": "Container Load", "value": "± 197 bal / 40ft HC", "value_en": "± 197 bales / 40ft HC"}]'::jsonb,'images/gallery-coco-fiber.webp','published',1)
