values ('cocopeat','Cocopeat','Cocopeat','Media Tanam','Media tanam organik 100% dari sabut kelapa. Melalui proses pencucian, penyaringan, dan kompresi, cocopeat memberikan daya serap air dan aerasi terbaik, cocok untuk hidroponik, pembibitan, dan campuran media tanam.','A 100% organic growing medium made from coconut husk. Through washing, screening, and compression, cocopeat delivers excellent water retention and air porosity, ideal for hydroponics, nurseries, and potting mix.','$150–250 USD / MT','200 Ton / Bulan','20 Ton / Kontainer 40ft (HC)','L/C, T/T','[{"id": "100% Organik & Berkelanjutan", "en": "100% Organic & Sustainable Growing Medium"}, {"id": "Pilihan Low EC (Washed) atau High EC", "en": "Low EC (Washed) or High EC Options Available"}, {"id": "Block Kompresi 5kg untuk Efisiensi Kirim", "en": "Compressed 5kg Blocks for Efficient Shipping"}]'::jsonb,'[{"label_id": "Supply Ability", "label_en": "Supply Ability", "value": "200 Ton / Bulan", "value_en": "200 Metric Tons / Month", "sub": ""}, {"label_id": "Kemasan & Pengiriman", "label_en": "Packaging & Delivery", "value": "20 Ton / Kontainer 40ft (HC)", "value_en": "20 Ton per 40ft Container (HC)", "sub": ""}, {"label_id": "Harga", "label_en": "Price", "value": "$150–250 USD / MT", "value_en": "", "sub": "Min. Order 20 MT (1 Kontainer)"}, {"label_id": "Pembayaran", "label_en": "Payment Terms", "value": "L/C, T/T", "value_en": "", "sub": ""}]'::jsonb,'[{"qty": "1 – 20 MT", "qty_en": "", "waktu": "14 hari", "waktu_en": "14 days"}, {"qty": "> 20 MT", "qty_en": "", "waktu": "Nego", "waktu_en": "To be negotiated"}]'::jsonb,'[{"label_id": "Asal Produksi", "label_en": "Place of Origin", "value": "Sidoarjo, Jawa Timur", "value_en": "Sidoarjo, East Java, Indonesia"}, {"label_id": "Nama Produk", "label_en": "Product Name", "value": "Cocopeat / Coir Peat", "value_en": "Cocopeat / Coir Peat"}, {"label_id": "Material", "label_en": "Material", "value": "100% Sabut Kelapa", "value_en": "100% Coconut Husk"}, {"label_id": "Level EC", "label_en": "EC Level", "value": "Low (≤ 0.5 mS/cm) / High", "value_en": "Low (≤ 0.5 mS/cm) or High"}, {"label_id": "pH", "label_en": "", "value": "5.5–6.5", "value_en": ""}, {"label_id": "Kadar Air", "label_en": "Moisture", "value": "≤ 20%", "value_en": ""}, {"label_id": "Rasio Kompresi", "label_en": "Compression Ratio", "value": "5 : 1", "value_en": ""}, {"label_id": "Kemasan", "label_en": "Packing", "value": "Block / Slab 5kg", "value_en": "5kg Block / Slab"}, {"label_id": "Muatan Kontainer", "label_en": "Container Load", "value": "± 1.100 block / 40ft HC", "value_en": "± 1,100 blocks / 40ft HC"}]'::jsonb,'images/gallery-cocopeat.webp','published',2)
