values ('cocomesh','Produk Turunan','Derivative Products','Produk Turunan','Rangkaian produk turunan sabut kelapa untuk reklamasi lahan, pembibitan, hingga media tanam ramah lingkungan, dibuat custom sesuai spesifikasi buyer.','A range of coconut fiber derivative products for land reclamation, seedling nurseries, and eco-friendly growing media, custom made to buyer specifications.','Hubungi Kami','Custom, Sesuai Permintaan','Roll / Karton, per Jenis Produk','L/C, T/T','[{"id": "Cocomesh untuk reklamasi lahan & kontrol erosi", "en": "Cocomesh for land reclamation & erosion control"}, {"id": "Cocopot & cocodisc untuk pembibitan tanaman", "en": "Coco pots & coco discs for seedling nurseries"}, {"id": "Ukuran & kepadatan custom sesuai kebutuhan", "en": "Custom size & density per buyer request"}]'::jsonb,'[{"label_id": "Supply Ability", "label_en": "Supply Ability", "value": "Custom, Sesuai Permintaan", "value_en": "Custom, on request", "sub": ""}, {"label_id": "Kemasan & Pengiriman", "label_en": "Packaging & Delivery", "value": "Roll / Karton, per Jenis Produk", "value_en": "Roll / carton, per product type", "sub": ""}, {"label_id": "Harga", "label_en": "Price", "value": "Hubungi Kami", "value_en": "Contact us for a quote", "sub": "Min. order nego per jenis produk"}, {"label_id": "Pembayaran", "label_en": "Payment Terms", "value": "L/C, T/T", "value_en": "", "sub": ""}]'::jsonb,'[{"qty": "Sampel / Trial Order", "qty_en": "Sample / trial order", "waktu": "7 hari", "waktu_en": "7 days"}, {"qty": "Order Reguler", "qty_en": "Regular order", "waktu": "14–21 hari", "waktu_en": "14–21 days"}, {"qty": "Order Besar / Custom", "qty_en": "Large / custom order", "waktu": "Nego", "waktu_en": "To be negotiated"}]'::jsonb,'[{"label_id": "Asal Produksi", "label_en": "Place of Origin", "value": "Sidoarjo, Jawa Timur", "value_en": "Sidoarjo, East Java, Indonesia"}, {"label_id": "Material", "label_en": "Material", "value": "100% Serat Sabut Kelapa Alami", "value_en": "100% Natural Coconut Coir Fiber"}, {"label_id": "Warna", "label_en": "Color", "value": "Coklat Alami", "value_en": "Natural Brown"}, {"label_id": "Ukuran Cocomesh", "label_en": "Cocomesh Size", "value": "Lebar 1–4m, panjang roll custom, mesh 2×2–5×5cm", "value_en": "Width 1–4m, custom roll length, mesh 2×2–5×5cm"}, {"label_id": "Ukuran Cocopot", "label_en": "Cocopot Size", "value": "Diameter 5–15cm, tinggi custom", "value_en": "Diameter 5–15cm, custom height"}, {"label_id": "Ukuran Cocodisc", "label_en": "Cocodisc Size", "value": "Diameter 5–10cm, tebal 1–2cm", "value_en": "Diameter 5–10cm, thickness 1–2cm"}, {"label_id": "Daya Urai", "label_en": "Biodegradation Period", "value": "2–5 tahun, tergantung ketebalan & kondisi tanah", "value_en": "2–5 years, depending on thickness & soil conditions"}, {"label_id": "Kemasan", "label_en": "Packaging", "value": "Roll (Cocomesh) / Karton (Cocopot, Cocodisc)", "value_en": "Roll (Cocomesh) / Carton box (Cocopot, Cocodisc)"}, {"label_id": "Minimum Order", "label_en": "Minimum Order", "value": "Nego per jenis produk & ukuran", "value_en": "To be negotiated per product type & size"}]'::jsonb,'images/cocomesh.webp','published',3)
